#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    long long n;               // number of rows requested
    char *endptr = NULL;
    long long row[61] = {0};    // holds current row, max 60 rows (61 elements)

    // ---------- error handling ----------
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {   // not a pure integer
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {                 // negative numbers are also bad
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) {                // array can hold at most 61 elements
        puts("OUT_OF_RANGE");
        return 0;
    }

    // ---------- Pascal's triangle ----------
    for (long long r = 0; r < n; ++r) {
        // first element of the row is always 1
        row[0] = 1;

        // compute the interior of the row (if any)
        for (long long c = r; c > 0; --c) {
            // row[c] = previous row[c-1] + previous row[c]
            row[c] = row[c] + row[c - 1];
        }

        // print the row
        for (long long c = 0; c <= r; ++c) {
            if (c > 0) putchar(' ');
            printf("%lld", row[c]);
        }
        putchar('\n');
    }

    return 0;
}
